ALTER TABLE "bounty_proposal" DROP CONSTRAINT "bounty_proposal_money_check";--> statement-breakpoint
ALTER TABLE "bounty_proposal" ADD CONSTRAINT "bounty_proposal_money_check" CHECK (("bounty_proposal"."complexity" = 'unsized' AND "bounty_proposal"."amount_minor" IS NULL AND "bounty_proposal"."currency" IS NULL) OR ("bounty_proposal"."complexity" <> 'unsized' AND "bounty_proposal"."amount_minor" IS NOT NULL AND "bounty_proposal"."amount_minor" > 0 AND "bounty_proposal"."amount_minor" <= 9007199254740991 AND "bounty_proposal"."currency" IS NOT NULL AND "bounty_proposal"."currency" ~ '^[A-Z]{3}$'));